use crate::{generated::*,model::*,unit_support::*};
fn bad(reference:&Game,g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(reference);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn generated_identity_is_explicit_and_does_not_delete_a_physical_card(){let mut g=game();let c=g.make_card("JC125",0);assert!(c.generated.is_none());assert!(!g.generated_disappears(&c));let id=c.id.clone();g.regions[0].cards.push(c);g.return_hand(&id);assert!(g.players[0].hand.iter().any(|c|c.definition=="JC125"));let c=g.make_card("TK010",0);assert!(c.generated.is_none());assert!(!g.generated_disappears(&c),"unmarked card cannot be deleted just by printed identity");assert!(g.validate_generated_identity(&c).is_err());restore(&mut g);}
#[test]fn generated_birth_identity_survives_hide_and_special_reveal(){let mut g=game();let id=field(&mut g,"TK010",0);let origin=g.board(&id).unwrap().1.generated.clone();g.hide_in_place(&id);let c=&g.regions[0].cards[0];assert!(c.face_down);assert_eq!(c.generated,origin);assert_ne!(c.id,id);restore(&mut g);}
#[test]fn generated_snapshot_rejects_missing_changed_or_transplanted_identity(){let mut g=game();let id=field(&mut g,"TK010",0);for n in 0..5{let mut x=g.clone();let c=x.board_mut(&id).unwrap();match n{0=>c.generated=None,1=>c.generated.as_mut().unwrap().kind=GeneratedKind::Police,2=>c.generated.as_mut().unwrap().owner=1,3=>c.generated.as_mut().unwrap().birth_instance="i999999999".into(),_=>c.definition="JC125".into()};bad(&g,&x);}restore(&mut g);}
#[test]fn generated_unregistered_kinds_fail_before_allocating_ids(){let mut g=game();let before=serde_json::to_string(&g).unwrap();for kind in [GeneratedKind::Police,GeneratedKind::Cultist,GeneratedKind::Walker]{assert!(g.make_generated(kind,0).is_err());assert_eq!(serde_json::to_string(&g).unwrap(),before);}assert!(g.make_generated(GeneratedKind::Tentacle,4).is_err());}

#[test]fn generated_two_live_instances_cannot_share_one_birth(){let mut g=game();let first=field(&mut g,"TK010",0);let second=field(&mut g,"TK010",0);let original=g.board(&first).unwrap().1.generated.clone();let mut x=g.clone();x.board_mut(&second).unwrap().generated=original;bad(&g,&x);restore(&mut g);}
#[test]fn generated_tentacle_payment_does_not_make_core_zone_an_ordinary_target(){let mut g=game();fund(&mut g,0,"JC069",2);let source=field(&mut g,"BQ045",0);let token=field(&mut g,"TK010",0);g.players[2].society_zone.card=Some(g.make_card("MSBQ02",2));let c=g.make_card("BQ046",2);let id=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:2,definition:"BQ046".into(),rest:0,card:Some(c)});restore(&mut g);assert!(g.in_play(&id).is_none());let src=g.source_snapshot(g.board(&source).unwrap().1,Some(0));let spec=crate::rules::target(crate::rules::Zone::Board,crate::rules::EntityKind::Character,crate::rules::Relation::Any,crate::rules::Range::Anywhere);let bound=BoundTarget{id:id.clone(),public:g.public_target(0,&src,&spec,&id),spec,region_instance:None};assert!(!g.valid_bound_target(0,&src,&bound));reject(&mut g,0,Action{card_id:Some(source),ability_id:Some(crate::bq045::HUNT.into()),cost_selected:Some(vec![token.clone()]),target_id:Some(id),..Action::new("activate")});assert_eq!(g.resources(0),2);assert!(!g.board(&token).unwrap().1.exhausted);}
